export function getLawBySlug(slug: string): Law | undefined {
  return laws.find(law => law.slug === slug);
}

export function getArticleByNumber(law: Law, articleNumber: number): LawArticle | undefined {
  return law.articles.find(article => article.number === articleNumber);
}

export function getRelatedArticles(law: Law, article: LawArticle): LawArticle[] {
  if (!article.relatedArticleNumbers || article.relatedArticleNumbers.length === 0) return [];
  return article.relatedArticleNumbers
    .map(num => law.articles.find(a => a.number === num))
    .filter((a): a is LawArticle => a !== undefined);
}

export function searchLaws(query: string): Law[] {
  const q = query.toLowerCase();
  return laws.filter(law =>
    law.title.includes(q) ||
    law.description.includes(q) ||
    law.category.includes(q)
  );
}

export function getLawsByCategory(category: string): Law[] {
  if (category === 'all') return laws;
  return laws.filter(law => law.category === category);
}

export function formatArticleNumber(num: number): string {
  return num.toLocaleString('fa-IR');
}
